SELECT city, COUNT(*) AS sample_count, AVG(us_aqi) AS avg_aqi, MIN(us_aqi) AS min_aqi, MAX(us_aqi) AS max_aqi, STDDEV_SAMP(us_aqi) AS sd_aqi, AVG(pm2_5) AS avg_pm2_5, AVG(pm10) AS avg_pm10, AVG(temperature_2m) AS avg_temp, AVG(relative_humidity_2m) AS avg_humidity, SUM(CASE WHEN us_aqi >= 100 THEN 1 ELSE 0 END) AS aqi_alert_count, SUM(CASE WHEN pm2_5 >= 35.5 THEN 1 ELSE 0 END) AS pm25_alert_count, SUM(CASE WHEN us_aqi >= 100 OR pm2_5 >= 35.5 THEN 1 ELSE 0 END) AS combined_alert_count FROM weather_airquality_records WHERE year='2026' AND month='10' AND day IN ('11','12','13','14','15','16','17','18') AND timestamp_utc >= '2026-10-11 17:00:00' AND timestamp_utc < '2026-10-18 17:00:00' GROUP BY city ORDER BY city;
